import{_ as d,C as c,o as a,c as i,a2 as t,b as p,w as o,a as n,E as l,a3 as s}from"./chunks/framework.DZUUNQ77.js";const _=JSON.parse('{"title":"IApplicationThreadCompat · 应用线程接口兼容","description":"","frontmatter":{},"headers":[],"relativePath":"reference/helper/compat/iapplication-thread-compat.md","filePath":"reference/helper/compat/iapplication-thread-compat.md","lastUpdated":1784063681000}'),A={name:"reference/helper/compat/iapplication-thread-compat.md"};function h(m,e,T,E,S,u){const r=c("Mermaid");return a(),i("div",null,[e[1]||(e[1]=t('<h1 id="iapplicationthreadcompat-·-应用线程接口兼容" tabindex="-1">IApplicationThreadCompat · 应用线程接口兼容 <a class="header-anchor" href="#iapplicationthreadcompat-·-应用线程接口兼容" aria-label="Permalink to &quot;IApplicationThreadCompat · 应用线程接口兼容&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">源码路径</p><p><a href="https://github.com/android-security-engineer/VirtualXposed-skills/blob/vxp/VirtualApp/lib/src/main/java/com/lody/virtual/helper/compat/IApplicationThreadCompat.java" target="_blank" rel="noreferrer"><code>src/main/java/com/lody/virtual/helper/compat/IApplicationThreadCompat.java</code></a></p></div><p><code>IApplicationThreadCompat</code> 抹平 <code>IApplicationThread</code> 这个隐藏接口的跨版本差异。<code>IApplicationThread</code> 是 server 反向驱动 client App 生命周期的 binder 接口（调度创建 Service、绑定、解绑、传参、停止），各版本方法签名不同，本类用反射按版本选正确签名调用。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方法</th><th>作用</th></tr></thead><tbody><tr><td><code>scheduleCreateService(appThread, token, info, …)</code></td><td>调度 <code>onCreate</code></td></tr><tr><td><code>scheduleBindService(appThread, token, intent, rebind, …)</code></td><td>调度 <code>onBind</code>/<code>onRebind</code></td></tr><tr><td><code>scheduleUnbindService(appThread, token, intent)</code></td><td>调度 <code>onUnbind</code></td></tr><tr><td><code>scheduleServiceArgs(appThread, token, taskRemoved, …)</code></td><td>调度 <code>onStartCommand</code></td></tr><tr><td><code>scheduleStopService(appThread, token)</code></td><td>调度 <code>onDestroy</code></td></tr></tbody></table><p>第一个参数 <code>appThread</code> 是 <code>IInterface</code>（client 传上来的 <code>IApplicationThread</code> 句柄），其余是具体调度参数。</p><h2 id="用途" tabindex="-1">用途 <a class="header-anchor" href="#用途" aria-label="Permalink to &quot;用途&quot;">​</a></h2><p><code>VActivityManagerService</code> 调度虚拟 Service 生命周期时，不能直接 <code>cast</code> 成某个版本的 <code>IApplicationThread</code> 调方法（签名可能对不上），而是把这些调用委托给本类，由它按 SDK 版本反射调用正确签名。</p><h2 id="service-生命周期反向驱动" tabindex="-1">Service 生命周期反向驱动 <a class="header-anchor" href="#service-生命周期反向驱动" aria-label="Permalink to &quot;Service 生命周期反向驱动&quot;">​</a></h2>',9)),(a(),p(s,null,{default:o(()=>[l(r,{id:"mermaid-80",class:"mermaid",graph:"sequenceDiagram%0A%20%20participant%20VAMS%20as%20VActivityManagerService%0A%20%20participant%20IAT%20as%20IApplicationThreadCompat%0A%20%20participant%20AT%20as%20client%20IApplicationThread%0A%20%20participant%20SVC%20as%20%E8%99%9A%E6%8B%9F%20Service%0A%20%20VAMS-%3E%3EIAT%3A%20scheduleCreateService(appThread%2C%20info)%0A%20%20IAT-%3E%3EIAT%3A%20%E6%8C%89%20SDK_INT%20%E9%80%89%E6%96%B9%E6%B3%95%E7%AD%BE%E5%90%8D%0A%20%20IAT-%3E%3EAT%3A%20%E5%8F%8D%E5%B0%84%E8%B0%83%E7%94%A8%E6%AD%A3%E7%A1%AE%20scheduleCreateService%0A%20%20AT-%3E%3ESVC%3A%20onCreate()%0A%20%20VAMS-%3E%3EIAT%3A%20scheduleServiceArgs(...)%0A%20%20IAT-%3E%3EAT%3A%20%E5%8F%8D%E5%B0%84%E8%B0%83%E7%94%A8%0A%20%20AT-%3E%3ESVC%3A%20onStartCommand()%0A%20%20VAMS-%3E%3EIAT%3A%20scheduleStopService(token)%0A%20%20IAT-%3E%3EAT%3A%20%E5%8F%8D%E5%B0%84%E8%B0%83%E7%94%A8%0A%20%20AT-%3E%3ESVC%3A%20onDestroy()%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="./application-thread-compat"><code>ApplicationThreadCompat</code></a>：负责把 binder 转成 <code>IInterface</code>。</li><li><a href="./../../server/am"><code>VActivityManagerService</code></a>：Service 调度调用方。</li><li><a href="/VirtualXposed-skills/features/activity-manager">活动管理</a>。</li></ul>',2))])}const b=d(A,[["render",h]]);export{_ as __pageData,b as default};
